WITH exploded AS (SELECT id, host, log_ts, level, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) t AS key, attr_value) SELECT key, DATE_TRUNC('DAY', log_ts) AS activity_day, BIT_AND(status_code) AS status_code_bit_and, PERCENTILE_APPROX(latency_ms, ARRAY(0.25, 0.5, 0.75)) AS latency_ms_quartiles, GROUPING_ID() AS gid FROM exploded GROUP BY GROUPING SETS ((key, DATE_TRUNC('DAY', log_ts)), (key)) ORDER BY key
